import test from 'node:test';import assert from 'node:assert/strict';import {generateChunk} from '../chunk-generation.js';import {resourceBlock,CHUNK,MIN_Y,HEIGHT,chunkIndex}from'../world.js';import {changedSections,mergeSections}from'../mesh-work.js';
test('fast generation preserves every natural block and edited builds through Y319 in both dimensions',()=>{for(const dimension of['overworld','nether'])for(const[cx,cz]of[[0,0],[-2,3]]){const edits=[{x:cx*16+3,y:319,z:cz*16+2,block:10},{x:cx*16+1,y:-30,z:cz*16+5,block:0}],data=generateChunk(cx,cz,dimension,edits);for(let y=MIN_Y;y<HEIGHT;y++)for(let z=0;z<CHUNK;z++)for(let x=0;x<CHUNK;x++){const edit=edits.find(a=>a.x===cx*16+x&&a.y===y&&a.z===cz*16+z);assert.equal(data[chunkIndex(x,y,z)],edit?edit.block:resourceBlock(cx*16+x,y,cz*16+z,dimension));}}});
test('mesh invalidation includes section seams and merges unfinished work without losing a full rebuild',()=>{assert.deepEqual([...changedSections(70)],[4]);assert.deepEqual([...changedSections(64)],[3,4]);assert.deepEqual([...changedSections(-16)],[-2,-1]);assert.deepEqual([...mergeSections(new Set([3,4]),changedSections(80))],[3,4,5]);assert.equal(mergeSections(null,changedSections(70)),null);assert.equal(mergeSections(new Set([4]),null),null);});
